extern int access(const char *, int);
extern int open(const char *, int, ...);
extern long write(int, const void *, unsigned long);
extern void _exit(int);
int main(void){
  const char *path = "/tmp/target";
  if (access(path, 2) == 0) {      /* W_OK: проверка (check) */
    int fd = open(path, 1);        /* O_WRONLY: использование (use) */
    write(fd, "x", 1);
  }
  _exit(0);
}
